/** Tab-aware stack reset — rebuilds the ROOT stack (a reset issued from a
 * tab screen must not reset the tab navigator with foreign routes). */
export function goReset(
  navigation: unknown,
  routes: Array<{ name: string; params?: unknown }>,
): void {
  let owner = navigation as NavLike;
  while (owner.getParent?.()) owner = owner.getParent()!;
  // a tab member only exists inside the tab group: the root stack gets the
  // group with that tab selected ("RESET … was not handled by any navigator")
  const rooted = routes.map((r) =>
    TAB_SCREENS.includes(r.name)
      ? {
          name: TAB_GROUP,
          params: r.params ? { screen: r.name, params: r.params } : { screen: r.name },
        }
      : r,
  );
  owner.reset?.({ index: rooted.length - 1, routes: rooted });
}
